  function drawSprite(index,x,y,size,rotation=0){if(!sprites.complete||!sprites.naturalWidth)return false;const sw=sprites.naturalWidth/4,sh=sprites.naturalHeight/2;ctx.save();ctx.translate(x,y);ctx.rotate(rotation);ctx.drawImage(sprites,(index%4)*sw,Math.floor(index/4)*sh,sw,sh,-size*.8,-size*.8,size*1.6,size*1.6);ctx.restore();return true;}
