  function beginTrainingStep(){state.mode='tutorial';state.trainingDummy=true;const drills=[{angle:45,prompt:'angle',coordinate:'x',key:'√2/2'},{angle:60,prompt:'angle',coordinate:'y',key:'√3/2'},{angle:60,prompt:'value',coordinate:'y',solution:'angle',key:'√3/2'},{angle:45,prompt:'value',coordinate:'x',solution:'angle',key:'√2/2'}],drill=drills[state.tutorialStep];resetWeaponButtons();state.unlockedQuadrants=1;unlockTrainingWeapons();const weapon=state.weapons.find(w=>w.key===drill.key)||state.weapons[0],angle=drill.angle,prompt=drill.prompt,solutionType=drill.solution||(prompt==='angle'?'value':'angle');state.trainingTarget=angle;state.enemies=[{id:'training',angle,r:orbitR+118,speed:0,kind:state.tutorialStep>=4?'shield-drone':'scout',size:25,spin:0,age:0,passed:false,open:true,value:weapon.value,valueKey:weapon.key,xKey:coordinateKey(angle,'x'),yKey:coordinateKey(angle,'y'),hp:state.tutorialStep===7?2:1,maxHp:state.tutorialStep===7?2:1,prompt,solutionType,mathName:drill.coordinate==='x'?'cos':'sin',coordinate:drill.coordinate}];state.trainingCoordinate=drill.coordinate;state.trainingValue=weapon.key;state.trainingMatchType=solutionType;state.activeWeaponType=state.trainingMatchType;state.activeAngleWeapon=angle;state.activeWeapon=Math.max(0,state.weapons.findIndex(w=>w.key===weapon.key));overlay.classList.add('hidden');$('weapon-rack').hidden=false;feed(`TRAINING STEP ${state.tutorialStep+1} · MATCH TARGET ${solutionType==='angle'?angleText(angle):weapon.key}`);updateHUD();updateTelemetry();}
