  function recordMinigame(success,reason='complete',score=0){const result={level:state.stage+1,content:['basic','reflection','quadrants','special-angle','boss'][state.stage]||'basic',success,reason,score,when:new Date().toISOString()};try{const results=JSON.parse(localStorage.getItem('orbit-defender-minigames')||'[]');results.push(result);localStorage.setItem('orbit-defender-minigames',JSON.stringify(results));localStorage.setItem('orbit-defender-minigame-current',JSON.stringify({...result,status:'complete'}));}catch(_){}return result;}
