  function finishRun(extracted,victory=false){if(state.runEnded)return;state.runEnded=true;state.mode=victory?'victory':'gameover';const record=recordRun(),title=victory?'Degree Overlord defeated':extracted?'ถอนตัวสำเร็จ':'Degree Core ดับลง',kicker=victory?'CAMPAIGN COMPLETE':extracted?'RUN EXTRACTED · LOOT SECURED':'RUN OVER',relicText=record.relics.length?record.relics.join(', '):'ไม่มี',loot=extracted||victory?`กู้คืน: ${relicText}`:`สูญเสีย: ${relicText}`,strength=record.weaponMatchAccuracy>=70?'เลือกอาวุธตรงสัญญาณได้ดี':`ฝึกจับคู่มุมกับอาวุธเพิ่ม (ความแม่น ${record.weaponMatchAccuracy}%)`,improve=record.weaponMismatches>0?`ลดการยิงผิดสัญญาณ ${record.weaponMismatches} ครั้ง`:'รักษาความแม่นยำและลดเวลาตัดสินใจ';showTerminal(kicker,title,'ผลการบินและข้อเสนอแนะอยู่ด้านล่าง','กลับสู่หน้าเมนู',restart,resultPresentation(record,kicker,loot,strength,improve));}
