    for(const b of [...state.bullets]){b.r+=b.speed*dt;b.life-=dt;if(b.isBoss&&stage.kind==='boss'&&Math.abs(delta(b.angle,state.bossAngle))<11&&Math.abs(b.r-(orbitR+126))<31){state.bullets=state.bullets.filter(x=>x!==b);if(b.canDamageBoss)hitBoss(b);else{const p=point(state.bossAngle,orbitR+126);burst(p.x,p.y,'#ff7180',6);feed('BOSS ARMOR DEFLECTED · WEAKPOINT MISMATCH');toast('IMPACT · WRONG WEAPON',true);sfx('hit');}continue;}if(b.targetType==='enemy_shot'){const shot=state.enemyShots.find(x=>x.id===b.targetId);if(shot&&Math.abs(delta(b.angle,shot.angle))<10&&Math.abs(b.r-shot.r)<23){state.bullets=state.bullets.filter(x=>x!==b);if(b.canDamageTarget){state.enemyShots=state.enemyShots.filter(x=>x!==shot);const p=point(shot.angle,shot.r);burst(p.x,p.y,'#73eaff',9);toast('HOSTILE SHOT INTERCEPTED');sfx('shield');}else{const p=point(shot.angle,shot.r);burst(p.x,p.y,'#ff7180',4);feed('SHOT IMPACT · MATCH x/y OR ANGLE TO INTERCEPT');sfx('hit');}continue;}}let hit=null;for(const e of state.enemies){if(e.id!==b.targetId)continue;if(Math.abs(delta(b.angle,e.angle))<10&&Math.abs(b.r-e.r)<25){hit=e;break;}}if(hit){state.bullets=state.bullets.filter(x=>x!==b);if(b.canDamageTarget&&hit.open)damageEnemy(hit,false,b.damage||1);else{const p=point(hit.angle,hit.r);burst(p.x,p.y,'#ff7180',5);feed('IMPACT · WRONG WEAPON VALUE · TARGET HOLDS');toast('SHOT LANDED · MATCH THE SIGNAL',true);sfx('hit');}continue;}if(b.r>screenSpawnRadius(b.angle,0))state.bullets=state.bullets.filter(x=>x!==b);}
