    function promptText(e){const coordinate=e.coordinate||'y';if(e.kind==='angle-seeker')return `x = ${e.xKey} · y = ${e.yKey}  →  θ = ?`;if(e.kind==='x-seeker')return `θ = ${angleText(e.angle)}  →  x = ?`;if(e.kind==='y-seeker')return `θ = ${angleText(e.angle)}  →  y = ?`;if(state.difficulty==='cadet'){const x=e.xKey||coordinateKey(e.angle,'x'),y=e.yKey||coordinateKey(e.angle,'y');return `θ = ${angleText(e.angle)} · x = ${x} · y = ${y}`;}if(state.difficulty==='ace')return e.prompt==='angle'?`ANGLE SIGNAL · FIND ${coordinate}`:`VALUE SIGNAL · FIND θ`;if(e.prompt==='angle')return `θ = ${angleText(e.angle)}  →  ${coordinate} = ?`;return `${coordinate} = ${e.valueKey}  →  θ = ?`;}
  function updateTelemetry(){if(state.mode==='tutorial'){const e=state.enemies[0];if(e){$('target-data').textContent=promptText(e);$('target-angle').textContent=`${e.solutionType==='angle'?'ANGLE CANNON · FIND θ':`VALUE CANNON · FIND ${e.coordinate}=${e.valueKey}`}`;$('target-distance').textContent=`ARMOR ${e.hp}/${e.maxHp}`;}else{$('target-data').textContent='TRAINING SIGNAL';$('target-angle').textContent='START THE NEXT FLIGHT DRILL';$('target-distance').textContent='ACADEMY';}return;}if(state.stage===4&&state.mode==='playing'){const boss={angle:state.bossAngle,valueKey:state.bossValueKey,prompt:state.bossPrompt,coordinate:state.bossCoordinate,mathName:state.bossCoordinate==='x'?'cos':'sin'};$('target-data').textContent=promptText(boss);$('target-angle').textContent=`BOSS WEAKPOINT · MATCH WEAPON`;$('target-distance').textContent=`${3-state.bossHits%3} ARMOR SEGMENTS`;return;}const e=nearestEnemy();if(e){$('target-data').textContent=e.kind==='shield-drone'&&!e.open?`PHASE SHIELD · ${promptText(e)}`:promptText(e);$('target-angle').textContent=`CHOOSE WEAPON · ${e.kind.toUpperCase()}`;$('target-distance').textContent=`${e.hp}/${e.maxHp} HP · ${Math.max(0,Math.ceil((e.r-orbitR)/e.speed))}s`;const showHint=Boolean(state.autoHint)&&state.autoHintKey===signalMistakeKey(e);$('auto-hint').hidden=!showHint;}else{$('target-data').textContent='NO CONTACT';$('target-angle').textContent='WEAPON SYSTEM READY';$('target-distance').textContent='—';$('auto-hint').hidden=true;}}function drawBackground(){ctx.fillStyle='#050718';ctx.fillRect(0,0,W,H);if(spaceArt.complete&&spaceArt.naturalWidth){const scale=Math.max(W/spaceArt.naturalWidth,H/spaceArt.naturalHeight),w=spaceArt.naturalWidth*scale,h=spaceArt.naturalHeight*scale;ctx.globalAlpha=.9;ctx.drawImage(spaceArt,(W-w)/2,(H-h)/2,w,h);ctx.globalAlpha=1;}const g=ctx.createRadialGradient(cx,cy,orbitR*.2,cx,cy,Math.max(W,H)*.62);g.addColorStop(0,'#07101b22');g.addColorStop(.55,'#07071825');g.addColorStop(1,'#02061277');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(const s of state.stars){ctx.globalAlpha=s.a*(.45+.55*Math.sin(state.time*1.3+s.p));ctx.fillStyle=s.s>1.2?'#c3f7ff':'#b9c7ff';ctx.beginPath();ctx.arc(s.x*W,s.y*H,s.s,0,TAU);ctx.fill();}ctx.globalAlpha=1;}
  function drawShieldDrops(){for(const drop of state.shieldDrops){const p=point(drop.angle,drop.r);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(state.time*1.6);ctx.shadowColor='#6ce8ff';ctx.shadowBlur=18;ctx.fillStyle='#0c5668';ctx.strokeStyle='#a5f5ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(10,-7);ctx.lineTo(8,7);ctx.lineTo(0,12);ctx.lineTo(-8,7);ctx.lineTo(-10,-7);ctx.closePath();ctx.fill();ctx.stroke();ctx.rotate(-state.time*1.6);ctx.fillStyle='#e5fcff';ctx.font='bold 13px Consolas,monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('+',0,1);ctx.restore();}}
  function drawEnemyShots(){for(const shot of state.enemyShots){const p=point(shot.angle,shot.r),tail=point(shot.angle,shot.r+19),label=promptText(shot);ctx.save();ctx.shadowColor=shot.color;ctx.shadowBlur=16;ctx.strokeStyle=shot.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(tail.x,tail.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.fillStyle='#fff2f5';ctx.beginPath();ctx.arc(p.x,p.y,3,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.font='bold 11px Consolas,monospace';const w=ctx.measureText(label).width+14;ctx.fillStyle='#071522f2';ctx.strokeStyle=shot.color+'cc';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(p.x-w/2,p.y-27,w,20,4);ctx.fill();ctx.stroke();ctx.fillStyle='#ffffff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,p.x,p.y-17);ctx.restore();}}
