  function spawnTravelEnemy(){const pad=36,edge=(Math.random()*4)|0;let x=edge===0?Math.random()*W:edge===1?W+pad:edge===2?Math.random()*W:-pad,y=edge===0?-pad:edge===1?Math.random()*H:edge===2?H+pad:Math.random()*H;const shipY=H*.76,dx=cx-x,dy=shipY-y,dist=Math.max(1,Math.hypot(dx,dy)),speed=35+Math.random()*24+state.clearedMissions*5,angle=[30,45,60,120,135,150][(Math.random()*6)|0],coordinate=Math.random()<.5?'x':'y';state.travelEnemies.push({x,y,vx:dx/dist*speed,vy:dy/dist*speed,r:13+Math.random()*5,angle,coordinate,valueKey:coordinateKey(angle,coordinate),age:0,spin:Math.random()*TAU});}
